// Compact HUD presentation; all decisions and mission data remain in their modules.
const fullHUD=refreshHUD;
refreshHUD=function(){const expanded=!!$('objective').querySelector('details')?.open;fullHUD();if(!playing)return;decorateVitals();const target=player.dead?'Your astronaut has died. You can watch your crew.':personalMissionObjective();const room=world.scene==='ext'?'Lunar surface':world.maps.base.rooms.find(r=>player.x>=r.x0*32&&player.x<=r.x1*32&&player.y>=r.y0*32&&player.y<=r.y1*32)?.key;document.querySelector('.mission>small').textContent=`${t('dayLabel')} ${state.day} · LEVEL ${state.difficulty||1} · ${Math.ceil(DAY_SECONDS-state.dayTime)}s · ${room?roomLabel(room):'Aurora Base'}`;const goals=$('objective').querySelector('.goals')?.outerHTML||'';$('objective').innerHTML=`<span style="color:#65d8ff">OBJECTIVE:</span> ${target}<details ${expanded?'open':''}><summary>Progress and reserves</summary>${goals}</details>`;};
const toolbar=document.createElement('nav');toolbar.id='cozyToolbar';toolbar.setAttribute('aria-label','Mission tools');$('hud').append(toolbar);
for(const [label,icon,action]of [['Logbook','▤',journal],['Controls','♧',controlsModal],['NASA data','◎',()=>environmentScreen(false)],['Settings','⚙',settingsModal]]){const b=document.createElement('button');b.textContent=icon;b.title=label;b.setAttribute('aria-label',label);b.onclick=action;toolbar.append(b)}

const vitalIcons={energy:'battery',life:'o2tank',safety:'locker',food:'planter2',water:'water',science:'lab_bench',radiation:'cryo'};
const vitalIconCache={};
function decorateVitals(){document.querySelectorAll('#stats .stat').forEach((el,i)=>{const key=[...statKeys,'radiation'][i],label=el.querySelector('label');if(!label)return;if(key==='radiation')el.title='Simulated environmental radiation for the whole crew. Your personal exposure is tracked separately.';if(key==='life')label.textContent=lang==='en'?'BASE OXYGEN':'OXYGEN · BASE';if(key==='food')label.textContent=lang==='en'?'FOOD STOCK':'ALIMENTOS · RESERVA';if(!vitalIconCache[key])vitalIconCache[key]=PIX.props[vitalIcons[key]].toDataURL();const img=document.createElement('img');img.src=vitalIconCache[key];img.alt='';img.className='vitalIcon';el.prepend(img);el.classList.toggle('critical',key==='radiation'?state.radiation>50:key!=='science'&&state[key]<20);});updatePersonalHUD();const stock=document.createElement('div');stock.className='stockReadout';stock.innerHTML=`<span>▥ MATERIALS <b>${Math.floor(state.materials)}</b></span><span>⚙ PARTS <b>${Math.floor(state.parts)}</b></span><span>▤ ANALYZED DUST <b>${state.mats.ice}</b></span><span>◆ ANALYZED ROCK <b>${state.mats.ore}</b></span>`;$('stats').append(stock);}
